package in.kabadiwala.connect.controller; import in.kabadiwala.connect.dto.ApiResponse;import in.kabadiwala.connect.model.*;import in.kabadiwala.connect.repository.*;import in.kabadiwala.connect.service.*;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*; @RestController @RequestMapping("/api/v1/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController {private final UserRepository users;private final RecyclerProfileRepository recyclers;private final LotRepository lots;private final QuotationRepository quotes;private final PickupRepository pickups;private final TransactionRepository tx;private final PaymentRepository payments;private final AuditLogRepository audits;private final DisputeRepository disputes;private final SystemSettingRepository settings;private final StoredDocumentRepository documents;private final NotificationService notes;private final AuditService audit;public AdminController(UserRepository u,RecyclerProfileRepository r,LotRepository l,QuotationRepository q,PickupRepository p,TransactionRepository t,PaymentRepository pay,AuditLogRepository a,DisputeRepository d,SystemSettingRepository s,StoredDocumentRepository docs,NotificationService n,AuditService au){users=u;recyclers=r;lots=l;quotes=q;pickups=p;tx=t;payments=pay;audits=a;disputes=d;settings=s;documents=docs;notes=n;audit=au;}@GetMapping("/dashboard")ApiResponse<?> dashboard(){return ApiResponse.ok("Dashboard",Map.of("collectors",users.findAll().stream().filter(x->x.role==Role.COLLECTOR).count(),"recyclers",users.findAll().stream().filter(x->x.role==Role.RECYCLER).count(),"pendingRecyclers",recyclers.findAll().stream().filter(x->"PENDING_VERIFICATION".equals(x.verificationStatus)).count(),"verifiedRecyclers",recyclers.findAll().stream().filter(x->"VERIFIED".equals(x.verificationStatus)).count(),"lots",lots.count(),"publishedLots",lots.findAll().stream().filter(x->x.status==LotStatus.PUBLISHED).count(),"transactions",tx.count(),"completedTransactions",tx.findAll().stream().filter(x->"COMPLETED".equals(x.status)).count(),"disputes",disputes.count()));}@GetMapping("/users")ApiResponse<?> users(@RequestParam(required=false)Role role,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){var p=users.findAll(PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending()));return ApiResponse.ok("Users",role==null?p:p.map(x->x).getContent().stream().filter(x->x.role==role).toList());}@GetMapping("/recyclers")ApiResponse<?> recyclerApps(@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){var pg=PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending());return ApiResponse.ok("Recyclers",status==null?recyclers.findAll(pg):recyclers.findByVerificationStatus(status,pg));}@PostMapping("/recyclers/{userId}/status")ApiResponse<?> status(Authentication auth,@PathVariable String userId,@RequestBody Map<String,String>b){String status=b.get("status"),reason=b.getOrDefault("reason","");if(!Set.of("VERIFIED","REJECTED","SUSPENDED","PENDING_VERIFICATION").contains(status))throw new IllegalArgumentException("Invalid recycler status");var u=users.findById(userId).orElseThrow();if(u.role!=Role.RECYCLER)throw new IllegalArgumentException("Not a recycler");String old=u.recyclerStatus;u.recyclerStatus=status;users.save(u);var rp=recyclers.findByUserId(userId).orElseThrow();rp.verificationStatus=status;rp.verificationReason=reason;rp.verificationHistory.add(new RecyclerProfile.VerificationEvent(status,auth.getName(),reason,Instant.now()));recyclers.save(rp);notes.send(userId,status.equals("VERIFIED")?"RECYCLER_APPROVED":"RECYCLER_"+status,"RECYCLER",userId,Map.of("reason",reason));audit.log(auth.getName(),"RECYCLER_"+status,"RECYCLER",userId,old,status,Map.of("reason",reason));return ApiResponse.ok("Recycler status updated",rp);}@GetMapping("/recyclers/{userId}/documents")ApiResponse<?> documents(@PathVariable String userId){return ApiResponse.ok("Recycler documents",documents.findByOwnerId(userId));}@GetMapping("/lots")ApiResponse<?> lots(){return ApiResponse.ok("Lots",lots.findAll());}@GetMapping("/quotations")ApiResponse<?> quotes(){return ApiResponse.ok("Quotations",quotes.findAll());}@GetMapping("/pickups")ApiResponse<?> pickups(){return ApiResponse.ok("Pickups",pickups.findAll());}@GetMapping("/transactions")ApiResponse<?> tx(){return ApiResponse.ok("Transactions",tx.findAll());}@GetMapping("/payments")ApiResponse<?> payments(){return ApiResponse.ok("Payments",payments.findAll());}@GetMapping("/audit-logs")ApiResponse<?> audits(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return ApiResponse.ok("Audit logs",audits.findAll(PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending())));}@GetMapping("/disputes")ApiResponse<?> disputes(){return ApiResponse.ok("Disputes",disputes.findAll());}@GetMapping("/settings")ApiResponse<?> settings(){return ApiResponse.ok("Settings",settings.findAll());}@PutMapping("/settings/{key}")ApiResponse<?> setting(Authentication a,@PathVariable String key,@RequestBody Map<String,String>b){var s=settings.findAll().stream().filter(x->x.key.equals(key)).findFirst().orElseGet(()->{var x=new SystemSetting();x.key=key;return x;});s.value=b.get("value");s.description=b.get("description");audit.log(a.getName(),"ADMIN_ACTION","SETTING",key,null,s.value,Map.of());return ApiResponse.ok("Setting saved",settings.save(s));}}
